from collections import defaultdict
V=[tuple(Fraction(x) for x in v) for v in geometry['objects'][0]['vertices']]
T=geometry['objects'][0]['triangles']
def sub(a,b): return tuple(x-y for x,y in zip(a,b))
def dot(a,b): return sum(x*y for x,y in zip(a,b))
def cross(a,b): return (a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0])
planes=[]; edges=defaultdict(list)
for ti,t in enumerate(T):
 p=[V[i] for i in t]; n=cross(sub(p[1],p[0]),sub(p[2],p[0])); scale=max(map(abs,n)); n=tuple(x/scale for x in n) if scale else n
 planes.append((n,dot(n,p[0])))
 for a,b in zip(p,p[1:]+p[:1]): edges[tuple(sorted((a,b)))].append(ti)
adj=defaultdict(set)
for ids in edges.values():
 for a in ids:
  for b in ids:
   if planes[a]==planes[b] and a!=b: adj[a].add(b)
components=[]; seen=set()
for start in range(len(T)):
 if start in seen: continue
 stack=[start]; seen.add(start); comp=[]
 while stack:
  curr=stack.pop(); comp.append(curr)
  for nxt in adj[curr]-seen: seen.add(nxt); stack.append(nxt)
 components.append(sorted(comp))
surfaces=[]; unsupported=[]
for comp in components:
 counts=defaultdict(int)
 for ti in comp:
  p=[V[i] for i in T[ti]]
  for a,b in zip(p,p[1:]+p[:1]): counts[tuple(sorted((a,b)))]+=1
 boundary=[e for e,c in counts.items() if c==1]; graph=defaultdict(list)
 for a,b in boundary: graph[a].append(b); graph[b].append(a)
 valid=bool(graph) and all(len(x)==2 for x in graph.values()) and all(c<=2 for c in counts.values())
 corners=[]
 if valid:
  start=next(iter(graph)); curr=start; prev=None; loop=[]
  while curr not in loop:
   loop.append(curr); nxt=next(x for x in graph[curr] if x!=prev); prev,curr=curr,nxt
  valid=curr==start and len(loop)==len(graph)
  corners=[p for i,p in enumerate(loop) if any(cross(sub(p,loop[i-1]),sub(loop[(i+1)%len(loop)],p)))]
  valid=valid and len(corners)==4
 if valid:
  es=[sub(corners[(i+1)%4],corners[i]) for i in range(4)]
  valid=all(dot(es[i],es[(i+1)%4])==0 and any(es[i]) for i in range(4)) and all(es[0][i]==-es[2][i] and es[1][i]==-es[3][i] for i in range(3))
 if valid:
  surfaces.append({'triangles':comp,'corners':corners,'normal':planes[comp[0]][0],'center':tuple(sum(p[i] for p in corners)/4 for i in range(3))})
 else: unsupported.append(comp)
print('supported',len(surfaces),'triangles',sum(len(s['triangles']) for s in surfaces),'unsupported',unsupported)
result=render_views(['SCENE','TOP','LEFT','RIGHT','FRONT','BACK'],include_images=False)
print(result)

tri_surface=np.full(len(T),-2,dtype=int)
for si,s in enumerate(surfaces): tri_surface[s['triangles']]=si
pixel_facts={}
for name,b in buffers.items():
 ids=b['triangle_ids']; labels=np.full(ids.shape,-1,dtype=int); valid=ids>=0; labels[valid]=tri_surface[ids[valid]]
 rgb=b['color'].astype(np.int32); marked=np.zeros(ids.shape,bool)
 for axis in [0,1]:
  aa=(slice(None,-1),slice(None)) if axis==0 else (slice(None),slice(None,-1))
  bb=(slice(1,None),slice(None)) if axis==0 else (slice(None),slice(1,None))
  diff=(labels[aa]!=labels[bb]) & (np.sum((rgb[aa]-rgb[bb])**2,axis=2)>=576)
  marked[aa]|=diff; marked[bb]|=diff
 for si in range(len(surfaces)):
  ys,xs=np.where(labels==si); count=len(xs)
  pixel_facts[(si,name)]={'pixels':count,'boundary':int(np.count_nonzero(marked & (labels==si))),'pixel':[int(xs[count//2]),int(ys[count//2])] if count else None}
print('SCENE query triangle',int(buffers['SCENE']['triangle_ids'][247,109]),'surface',int(tri_surface[buffers['SCENE']['triangle_ids'][247,109]]))
def clip(poly, f):
 if not poly:return []
 out=[]; prev=poly[-1]; fp=f(prev)
 for curr in poly:
  fc=f(curr)
  if (fp>=0)!=(fc>=0):
   ratio=fp/(fp-fc); out.append(tuple(a+ratio*(b-a) for a,b in zip(prev,curr)))
  if fc>=0:out.append(curr)
  prev=curr; fp=fc
 return out
def area2(poly):return abs(sum(poly[i][0]*poly[(i+1)%len(poly)][1]-poly[i][1]*poly[(i+1)%len(poly)][0] for i in range(len(poly)))) if poly else 0
geom_facts={}
for cam in cameras['views']:
 name=cam['name']; d=tuple(map(Fraction,cam['direction_rational'])); seed=(0,1,0) if name=='TOP' else (0,0,1); r=cross(seed,d); u=cross(d,r)
 proj=[(dot(r,p),dot(u,p),dot(d,p)) for p in V]; pt=[[proj[i] for i in t] for t in T]
 mins=np.array([[float(min(p[k] for p in t)) for k in range(2)] for t in pt]); maxs=np.array([[float(max(p[k] for p in t)) for k in range(2)] for t in pt])
 for si,s in enumerate(surfaces):
  front=dot(s['normal'],d)>0; fact={'front':front,'inside':True,'complete':False,'occluder_triangle':None}
  if front:
   q=[(dot(r,p),dot(u,p),dot(d,p)) for p in s['corners']]
   if sum(q[i][0]*q[(i+1)%4][1]-q[i][1]*q[(i+1)%4][0] for i in range(4))<0:q=q[::-1]
   pn=cross(sub(q[1],q[0]),sub(q[2],q[0]));
   def gap(p):return (dot(pn,q[0])-pn[0]*p[0]-pn[1]*p[1])/pn[2]
   lo=np.array([float(min(p[k] for p in q)) for k in range(2)]); hi=np.array([float(max(p[k] for p in q)) for k in range(2)])
   candidates=np.where(np.all(maxs>lo,axis=1)&np.all(mins<hi,axis=1))[0]
   for ti in candidates:
    if tri_surface[ti]==si:continue
    poly=pt[ti]
    for j in range(4):
     a=q[j]; b=q[(j+1)%4]
     poly=clip(poly,lambda p,a=a,b=b:(b[0]-a[0])*(p[1]-a[1])-(b[1]-a[1])*(p[0]-a[0]))
     if not poly:break
    poly=clip(poly,lambda p:p[2]-gap(p))
    if area2(poly)>0 and any(p[2]>gap(p) for p in poly):fact['occluder_triangle']=int(ti);break
   fact['complete']=fact['occluder_triangle'] is None
  geom_facts[(si,name)]=fact
print('geometry and pixels calculated')
for center in [(0,0,0),(Fraction(5,32),Fraction(-5,32),Fraction(237,2048))]:
 for si,s in enumerate(surfaces):
  if s['center']==center:
   print('target',si,str(s),{c['name']:{**geom_facts[(si,c['name'])],**pixel_facts.get((si,c['name']),{})} for c in cameras['views']})

